bg = 5
output_rows, output_cols = 24, 20

# Get zone membership for each output cell
cell_zones = {}
for r_out in range(output_rows):
    for c_out in range(output_cols):
        mr = ((r_out // 3) % 9)
        mc = ((c_out // 2) % 9)
        cell_zones[(r_out, c_out)] = (mr, mc)

base_patterns = base_patterns

# For each zone, determine closest active input value  
zone_values = {}
for z_m_r in range(9):
    for z_m_c in range(9):
        center_r = z_m_r * 1.5
        center_c = z_m_c * 2 + 1

        min_dist = float('inf')
        best_val = bg
        for ir in range(8):
            for ic in range(10):
                if test_input[ir,ic] != bg:
                    dist = (ir - center_r)**2 + (ic - center_c)**2
                    if dist < min_dist:
                        min_dist = dist
                        best_val = test_input[ir,ic]

        zone_values[(z_m_r, z_m_c)] = best_val

output_grid = np.full((output_rows, output_cols), bg, dtype=int)

# Fill: If zone has non-empty pattern AND local position matches, use zone's closest value
# BUT only fill cells where local position EXACTLY equals some pattern coordinate
for r_out in range(output_rows):
    for c_out in range(output_cols):
        mr_zone = ((r_out // 3) % 9)
        mc_zone = ((c_out // 2) % 9)

        pat_key = (mr_zone, mc_zone)
        pattern = set(base_patterns.get(pat_key, frozenset()))

        rel_row = r_out % 3
        rel_col = c_out % 2

        if (rel_row, rel_col) in pattern:
            val = zone_values[mr_zone, mc_zone]
            if val != bg:
                output_grid[r_out, c_out] = val

fg_count = np.sum((output_grid != bg).flatten())
print(f"FG count: {fg_count}")

# Check specific positions filled
